using Microsoft.Extensions.Options;
using YoungOne.MediaControl.Agent.Detection;
using YoungOne.MediaControl.Agent.Identity;
using YoungOne.MediaControl.Agent.Transport;
namespace YoungOne.MediaControl.Agent;
public sealed class AgentWorker(MediaControlClient client,AgentRuntimeStatusProvider runtime,AgentCredentialStore credentials,IUserNotifier notifier,IOptions<AgentOptions> options,ILogger<AgentWorker> logger):BackgroundService{
 protected override async Task ExecuteAsync(CancellationToken stoppingToken){TimeSpan normal=TimeSpan.FromSeconds(options.Value.HeartbeatSeconds);int failures=0;while(!stoppingToken.IsCancellationRequested){try{AgentCredential credential=await client.EnsureRegisteredAsync(stoppingToken);await client.RefreshPolicyAsync(credential,stoppingToken);AgentRuntimeSnapshot snapshot=await runtime.GetAsync(stoppingToken);await client.HeartbeatAsync(credential,snapshot,stoppingToken);await notifier.PublishStatusAsync("ONLINE",snapshot.ControlStatus,"Server heartbeat succeeded",stoppingToken);failures=0;await Task.Delay(normal,stoppingToken);}catch(OperationCanceledException)when(stoppingToken.IsCancellationRequested){break;}catch(Exception ex){failures++;AgentRuntimeSnapshot snapshot=await runtime.GetAsync(stoppingToken);string connectivity=credentials.Load() is null?"NEVER_CONNECTED":snapshot.ControlStatus=="BOOTSTRAP_DETECT_ONLY"?"OFFLINE_DETECT_ONLY":snapshot.ControlStatus=="FAILSAFE"?"FAILSAFE":"OFFLINE_LAST_POLICY";await notifier.PublishStatusAsync(connectivity,snapshot.ControlStatus,"Server heartbeat failed",stoppingToken);TimeSpan delay=TimeSpan.FromSeconds(Math.Min(300,Math.Pow(2,Math.Min(failures,8))))+TimeSpan.FromMilliseconds(Random.Shared.Next(1000));logger.LogError(ex,"Agent communication failed; retrying in {Delay}",delay);await Task.Delay(delay,stoppingToken);}}}
}